import java.util.Optional;

public class OptionalDemo {
    public static void main(String[] args) {
        String cachedName = "Enterprise-Service";

        // ANTI-PATTERN: orElse executes the expensive fallback even when cachedName is present
        String badResult = Optional.ofNullable(cachedName)
                .orElse(fetchFallbackFromDatabase());

        // BEST PRACTICE: orElseGet defers execution; fetchFallbackFromDatabase() is never called
        String goodResult = Optional.ofNullable(cachedName)
                .orElseGet(() -> fetchFallbackFromDatabase());
    }

    private static String fetchFallbackFromDatabase() {
        System.out.println("Executing expensive database query...");
        return "Fallback-Service";
    }
}
